public class DOMNodePointer_findEnclosingAttribute_TriageGen0Test {

    /**
     * Helper method to invoke the protected static method via reflection.
     */
    private String invokeFindEnclosingAttribute(Node n, String attrName) throws Exception {
        Method method = DOMNodePointer.class.getDeclaredMethod("findEnclosingAttribute", Node.class, String.class);
        method.setAccessible(true);
        return (String) method.invoke(null, n, attrName);
    }

    @Test
    public void testFindEnclosingAttribute_NullNode() throws Exception {
        assertNull(invokeFindEnclosingAttribute(null, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_ElementWithAttributeFound() throws Exception {
        Element root = mock(Element.class);
        Element child = mock(Element.class);

        when(root.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(root.getAttribute("target")).thenReturn("value");
        when(child.getParentNode()).thenReturn(root);
        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);

        // Child exists but doesn't have the attribute, parent does
        when(child.getAttribute("target")).thenReturn(""); 

        assertEquals("value", invokeFindEnclosingAttribute(child, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_ElementWithAttributeDirectly() throws Exception {
        Element element = mock(Element.class);
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("target")).thenReturn("found");

        assertEquals("found", invokeFindEnclosingAttribute(element, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_NonElementNodeTraversesUp() throws Exception {
        Element parent = mock(Element.class);
        Node textNode = mock(Node.class);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("target")).thenReturn("parentValue");

        when(textNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(textNode.getParentNode()).thenReturn(parent);

        assertEquals("parentValue", invokeFindEnclosingAttribute(textNode, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeIsEmptyOrNull() throws Exception {
        Element root = mock(Element.class);
        Element middle = mock(Element.class);
        Element leaf = mock(Element.class);

        // Root has the value
        when(root.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(root.getAttribute("target")).thenReturn("success");

        // Middle has empty attribute
        when(middle.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(middle.getAttribute("target")).thenReturn("");
        when(middle.getParentNode()).thenReturn(root);

        // Leaf has null attribute
        when(leaf.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(leaf.getAttribute("target")).thenReturn(null);
        when(leaf.getParentNode()).thenReturn(middle);

        assertEquals("success", invokeFindEnclosingAttribute(leaf, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_NoAttributeFoundInHierarchy() throws Exception {
        Element element = mock(Element.class);
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("missing")).thenReturn("");
        when(element.getParentNode()).thenReturn(null);

        assertNull(invokeFindEnclosingAttribute(element, "missing"));
    }

    @Test
    public void testFindEnclosingAttribute_DeepHierarchySearch() throws Exception {
        Element root = mock(Element.class);
        Element level1 = mock(Element.class);
        Element level2 = mock(Element.class);
        Element level3 = mock(Element.class);

        when(root.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(root.getAttribute("target")).thenReturn("deepValue");

        when(level1.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(level1.getAttribute("target")).thenReturn("");
        when(level1.getParentNode()).thenReturn(root);

        when(level2.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(level2.getAttribute("target")).thenReturn(null);
        when(level2.getParentNode()).thenReturn(level1);

        when(level3.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(level3.getParentNode()).thenReturn(level2);

        assertEquals("deepValue", invokeFindEnclosingAttribute(level3, "target"));
    }
}
